{
    if (type == CCDB_TYPE_UINT16) {
        this->value.type = CCDB_TYPE_UINT16;
        this->value.val.uiv16 = *(CCDB_UINT16 *)value;  
    } else if (type == CCDB_TYPE_UINT32) {
        this->value.type = CCDB_TYPE_UINT32;
        this->value.val.uiv32 = *(CCDB_UINT32 *)value;  
    } else {
        std::cerr << "Parameter verification failed, type : " << type << std::endl;
        return false;
    }

    return true;
}

